// ---------- T8 Cardinal virtues: prudence (2), justice (2), fortitude (1), temperance (1) ----------
// Summa quotations: Dominican translation (1920), checked by script against New Advent. Scripture: Douay-Rheims. Evidence checked on PubMed (3 Nov 2026).
addTerms([
 {id:"prudence-parts",t:"Parts of prudence",la:"partes prudentiae",d:"Moral theology",b:"The eight integral parts (memory, understanding, docility, shrewdness, reasoning, foresight, circumspection, caution), the subjective parts (personal, domestic, political, military prudence) and the potential parts (good counsel, good judgment in ordinary cases, and in exceptional cases).",p:"ST II-II q.48 a.1. Five integral parts belong to prudence as knowing, three as commanding. The potential parts are eubulia (taking good counsel), synesis (judging well according to common law) and gnome (judging well when the common law fails) (q.51).",ex:"Before choosing a module, you remember past results (memory), ask a senior (docility), and weigh the timetable (circumspection).",where:"II-II qq.48–51",ccc:"1806",conf:"A checklist one ticks; the parts are aspects of one act of practical wisdom.",rel:["prudence","gifts-spirit"],lesson:"t8pr1",alias:["parts of prudence","docility","circumspection","foresight","eubulia","synesis","gnome","shrewdness"]},
 {id:"imprudence",t:"Imprudence and false prudence",la:"imprudentia; prudentia carnis; astutia",d:"Moral theology",b:"Imprudence fails in the acts of prudence (precipitation, thoughtlessness, inconstancy, negligence); false prudence is clever at reaching a bad end (prudence of the flesh) or uses counterfeit means (craftiness, guile, fraud).",p:"II-II qq.53–55. Every sin shares in imprudence \"because no sin can occur, without some defect in an act of the directing reason\" (q.53 a.2). The vices of imprudence arise chiefly from lust, which \"absorbs the mind\" (q.53 a.6); false prudence chiefly from avarice (q.55 a.8).",ex:"Signing a contract on impulse (precipitation); never deciding at all (negligence).",where:"II-II qq.53–56",ccc:"1806",conf:"Caution; or intelligence as such.",rel:["prudence"],lesson:"t8pr2",alias:["imprudence","precipitation","thoughtlessness","inconstancy","negligence","craftiness","prudence of the flesh","guile","solicitude"]},
 {id:"commutative-justice",t:"Commutative and distributive justice",la:"iustitia commutativa, distributiva",d:"Moral theology",b:"Commutative justice governs exchanges between persons (equality of thing to thing); distributive justice governs what the community owes its members (proportion to merit, need or role); legal (general) justice directs acts to the common good.",p:"ST II-II q.61 a.1–2; q.58 aa.5–7. Commutative justice is violated by theft, fraud, unjust contracts; it alone strictly binds to restitution (q.62). Distributive justice is violated by 'respect of persons' (q.63): favouritism.",ex:"Paying the agreed fee (commutative); a lecturer marking on merit, not friendship (distributive).",where:"II-II qq.57–63",ccc:"2411–2412",conf:"Equality of outcome in every case.",rel:["justice","common-good"],lesson:"t8ju1",alias:["commutative justice","distributive justice","legal justice","general justice","respect of persons","favouritism"]},
 {id:"restitution",t:"Restitution",la:"restitutio",d:"Moral theology",b:"The act of commutative justice by which what was unjustly taken or damaged is returned or compensated, restoring equality.",p:"\"Since therefore the safeguarding of justice is necessary for salvation, it follows that it is necessary for salvation to restore what has been taken unjustly\" (II-II q.62 a.2). Where exact repayment is impossible, one repays what one can. CCC 2412, 2487.",ex:"Repaying a friend for a borrowed item you broke; paying back an overcharge.",where:"II-II q.62",ccc:"2412, 2454, 2487",conf:"An apology alone; or a penalty paid to the State.",rel:["justice","commutative-justice"],lesson:"t8ju1",alias:["restitution","reparation","making amends"]},
 {id:"religion-virtue",t:"Religion (the virtue)",la:"religio",d:"Moral theology",b:"The moral virtue, annexed to justice, by which we render to God the worship due to Him as first principle of all things.",p:"\"Religion is not a theological virtue whose object is the last end, but a moral virtue which is properly about things referred to the end\" (II-II q.81 a.5). Interior acts: devotion and prayer (qq.82–83); exterior: adoration, sacrifice, oblations, vows, oaths (qq.84–89). Opposed by superstition (excess) and irreligion (defect) (q.92).",ex:"Going to Mass when tired, because God is owed worship, not because you feel like it.",where:"II-II qq.81–100",ccc:"2095–2109",conf:"Feeling religious; or faith itself (faith believes God; religion worships Him).",rel:["justice","devotion","faith"],lesson:"t8ju2",alias:["religion","virtue of religion","worship","adoration","superstition","irreligion","sacrilege"]},
 {id:"piety-gratitude",t:"Piety, observance, obedience and gratitude",la:"pietas, observantia, oboedientia, gratia",d:"Moral theology",b:"Potential parts of justice that render what is due where exact equality is impossible: to parents and country (piety), to those in authority (observance, obedience), to benefactors (gratitude).",p:"After God, \"man is debtor chiefly to his parents and his country\" (II-II q.101 a.1). Obedience binds within the sphere of a superior's authority, never against God (q.104 a.5; Acts 5:29). Gratitude follows the order of debts: God, parents, those excelling in dignity, benefactors (q.106 a.1).",ex:"Phoning your parents; thanking a tutor who gave extra time.",where:"II-II qq.101–106",ccc:"2197–2257",conf:"Blind obedience; or 'piety' as mere devoutness.",rel:["justice","religion-virtue"],lesson:"t8ju2",alias:["piety","filial piety","patriotism","observance","obedience","gratitude","thankfulness","ingratitude"]},
 {id:"magnanimity",t:"Magnanimity and its opposites",la:"magnanimitas; pusillanimitas; praesumptio",d:"Moral theology",b:"Greatness of soul: the part of fortitude that stretches the mind to great deeds worthy of honour, according to reason. Opposed by presumption, ambition and vainglory (excess) and pusillanimity (defect).",p:"\"Magnanimity by its very name denotes stretching forth of the mind to great things\" (II-II q.129 a.1). Humility and magnanimity concur: humility restrains from tending to great things against right reason, magnanimity urges to them in accord with it (q.161 a.1 ad 3). Pusillanimity refuses to tend to what is commensurate with one's power (q.133 a.1).",ex:"Applying for Honours although it is daunting, because you have the gifts; refusing out of fear would be pusillanimity.",where:"II-II qq.129–133",ccc:"1808",conf:"Arrogance; or ambition for its own sake.",rel:["fortitude","humility"],lesson:"t8fo",alias:["magnanimity","greatness of soul","pusillanimity","faint-heartedness","presumption","vainglory","ambition"]},
 {id:"patience",t:"Patience and perseverance",la:"patientia, perseverantia",d:"Moral theology",b:"Parts of fortitude: patience keeps reason from being broken by sorrow; perseverance persists in a good work over a long time until it is accomplished.",p:"Patience safeguards \"the good of reason against sorrow, lest reason give way to sorrow\" (II-II q.136 a.1). \"To persist long in something good until it is accomplished belongs to a special virtue\" (q.137 a.1). Final perseverance is a gift of grace (I-II q.109 a.10).",ex:"Continuing a hard degree through a discouraging semester.",where:"II-II qq.136–138",ccc:"1808, 2016",conf:"Passivity in the face of injustice.",rel:["fortitude","sorrow","hope"],lesson:"t8fo",alias:["patience","perseverance","longanimity","constancy","endurance","softness","pertinacity"]},
 {id:"martyrdom",t:"Martyrdom",la:"martyrium",d:"Moral theology",b:"The endurance of death for the truth of Christ (faith or any virtue referred to God), the highest act of fortitude.",p:"\"Martyrdom is the most perfect of human acts in respect of its genus, as being the sign of the greatest charity\" (II-II q.124 a.3; John 15:13). Its cause is not the punishment but the cause for which one suffers.",ex:"The Ugandan martyrs (1885–87); St Thomas More (1535).",where:"II-II q.124",ccc:"2473–2474",conf:"Any death in a religious context; or seeking death.",rel:["fortitude","charity"],lesson:"t8fo",alias:["martyrdom","martyr","martyrs","witness"]},
 {id:"humility",t:"Humility",la:"humilitas",d:"Moral theology",b:"The part of temperance (modesty) that restrains the mind from tending immoderately to high things, grounded in knowledge of one's real condition before God.",p:"A twofold virtue is needed about the difficult good: \"one, to temper and restrain the mind, lest it tend to high things immoderately; and this belongs to the virtue of humility\" (II-II q.161 a.1). Opposed by pride, the beginning of all sin (q.162 a.7; Sirach 10:15).",ex:"Accepting a correction from a younger colleague and acting on it.",where:"II-II qq.161–162",ccc:"2559, 2540",conf:"Low self-esteem or self-denigration (see 'irony', II-II q.113).",rel:["temperance","magnanimity","pride"],lesson:"t8te",alias:["humility","humble","pride","proud","modesty"]},
 {id:"studiousness",t:"Studiousness and curiosity",la:"studiositas; curiositas",d:"Moral theology",b:"Studiousness moderates the desire to know, urging diligent study of what one ought to know; curiosity is its disordered excess (seeking knowledge wrongly, of the wrong things, or at the cost of duty).",p:"\"Just as in respect of his corporeal nature man naturally desires the pleasures of food and sex, so, in respect of his soul, he naturally desires to know something… The moderation of this desire pertains to the virtue of studiousness\" (II-II q.166 a.2). Curiosity includes studying to the neglect of duty and seeking sensible knowledge without due order (q.167 aa.1–2).",ex:"Studying for the exam rather than scrolling news for hours.",where:"II-II qq.166–167",ccc:"2525–2526",conf:"Intellectual curiosity as such (which is good); or laziness alone (studiousness also checks excess).",rel:["temperance","acedia"],lesson:"t8te",alias:["studiousness","curiosity","doomscrolling","distraction"]}
]);

